    "location": "Collection David Hockney Foundation",
    "imgSrc": "https://lh3.googleusercontent.com/pw/AP1GczNsulmIhFflPwZsrKY3XDjCRrw7eSZttwXLDkigONHOMq2CFeNgnKiJJu6GLDRFkF-v2KYN4lOuFu7n_HQg1JvC1FNIMhmWE6wVtIldKAnbu7h6oWrZU6i3Fj9Rx2Uegmu59H_ipkvK7ocGMRxc_R_z9w=w1681-h1265-s-no-gm?authuser=0",
    "image": "https://lh3.googleusercontent.com/pw/AP1GczNsulmIhFflPwZsrKY3XDjCRrw7eSZttwXLDkigONHOMq2CFeNgnKiJJu6GLDRFkF-v2KYN4lOuFu7n_HQg1JvC1FNIMhmWE6wVtIldKAnbu7h6oWrZU6i3Fj9Rx2Uegmu59H_ipkvK7ocGMRxc_R_z9w=w1681-h1265-s-no-gm?authuser=0",
    "civilization": "Grande-Bretagne",
