    "image": "https://lh3.googleusercontent.com/pw/AP1GczMo-JbbnrBfzoU_7KS2Oixfvs1pUAHWWr2zMhbYJHFuYNKktJtt1vHGqf6_RMuDLsSCSRMA1jTwTa-geUGNtmz8aaJtqNAHl-JpqWOUjqSu_XmXF0_S0G-WI4NMRdTbrJgp1UkzXHHKadWmVkFmzE0SPA=w1681-h1121-s-no-gm?authuser=0",
    "civilization": "Grande-Bretagne",
